@RationalTickets.compile_tickets_positive
     : forall (A : Type) (mu : list (rat.rat * A)),
       is_true (ssrnat.leq 1 (@fst nat (list A) (@RationalTickets.compile_tickets A mu)))

@RationalTickets.ticket_outcomes_size
     : forall (A : Type) (mu : Representation.SubEnumQ A),
       @seq.size (option A) (@RationalTickets.ticket_outcomes A mu) =
       @RationalTickets.ticket_count A mu

@RationalTickets.ticket_outcomes_enumerated
     : forall (A : Type) (mu : Representation.SubEnumQ A),
       @seq.map nat (option A) (@RationalTickets.draw_ticket A mu)
         (seq.iota 0 (@RationalTickets.ticket_count A mu)) = @RationalTickets.ticket_outcomes A mu

@RationalTickets.uniform_ticket_returns
     : forall (A : Type) (mu : Representation.SubEnumQ A) (f : A -> rat.rat),
       @RationalTickets.ticket_expectation A mu
         (fun v : option A =>
          match v with
          | @Some _ x => f x
          | @None _ => @ssralg.GRing.zero rat.rat_rat__canonical__GRing_Nmodule
          end) =
       @FiniteEnum.finite_expect rat.rat_rat__canonical__Num_NumDomain A f
         (@Representation.subenumQ_data A mu)

@RationalTickets.ticket_sample_valid
     : forall (Seed A : Type) (next : nat -> Seed -> option nat * Seed)
         (mu : Representation.SubEnumQ A) (s s' : Seed) (i : nat),
       next (@RationalTickets.ticket_count A mu) s = (@Some nat i, s') ->
       is_true (ssrnat.leq (S i) (@RationalTickets.ticket_count A mu)) ->
       @RationalTickets.ticket_sample Seed A next mu s =
       (match @RationalTickets.draw_ticket A mu i with
        | @Some _ x => @Runner.Drawn A x
        | @None _ => @Runner.Missing A
        end, s')

@RationalTickets.ticket_sample_invalid
     : forall (Seed A : Type) (next : nat -> Seed -> option nat * Seed)
         (mu : Representation.SubEnumQ A) (s s' : Seed) (i : nat),
       next (@RationalTickets.ticket_count A mu) s = (@Some nat i, s') ->
       is_true (ssrnat.leq (@RationalTickets.ticket_count A mu) i) ->
       @RationalTickets.ticket_sample Seed A next mu s = (@Runner.NoEntropy A, s')

@RationalState.rational_counter
     : forall Seed : Type,
       (nat -> Seed -> option nat * Seed) -> nat -> nat -> Seed -> Runner.outcome nat * Seed
